enum {
    OPEN_CFW_MSPI0_BASE = 0x40060000U,
    OPEN_CFW_MSPI_STRIDE = 0x1000U,
    OPEN_CFW_MSPI_PADOUTEN = 0x44U,
    OPEN_CFW_MSPI_DEV0CFG = 0x84U,
    OPEN_CFW_MSPI_DEV0XIP = 0x90U,
};

typedef struct open_cfw_mspi_device_mode {
    uint8_t device;
    uint8_t separate_io;
    uint8_t mixed;
    uint32_t pad_output;
    uint32_t d4_pad_output;
} open_cfw_mspi_device_mode;

static const open_cfw_mspi_device_mode open_cfw_device_modes[26] = {
    {1, 1, 0, 0x103U, 0x80000013U}, {2, 1, 0, 0x103U, 0x80000013U},
    {5, 0, 0, 0x103U, 0x80000013U}, {6, 0, 0, 0x103U, 0x80000013U},
    {9, 0, 0, 0x10FU, 0x8000001FU}, {10, 0, 0, 0x10FU, 0x8000001FU},
    {13, 0, 0, 0x3FFU, 0}, {14, 0, 0, 0x3FFU, 0},
    {13, 0, 0, 0x3FFU, 0}, {14, 0, 0, 0x3FFU, 0},
    {17, 0, 0, 0x7FFFFU, 0}, {18, 0, 0, 0x7FFFFU, 0},
    {1, 0, 1, 0x103U, 0x80000013U}, {2, 0, 1, 0x103U, 0x80000013U},
    {1, 0, 3, 0x103U, 0x80000013U}, {2, 0, 3, 0x103U, 0x80000013U},
    {1, 0, 5, 0x10FU, 0x8000001FU}, {2, 0, 5, 0x10FU, 0x8000001FU},
    {1, 0, 7, 0x10FU, 0x8000001FU}, {2, 0, 7, 0x10FU, 0x8000001FU},
    {1, 0, 0, 0x103U, 0x80000013U}, {2, 0, 0, 0x103U, 0x80000013U},
    {1, 0, 9, 0x3FFU, 0}, {2, 0, 9, 0x3FFU, 0},
    {1, 0, 11, 0x3FFU, 0}, {2, 0, 11, 0x3FFU, 0},
};

uint32_t open_cfw_bootloader_mspi_device_configure_424120(
    const open_cfw_mspi_device_configure_context *instance,
    const open_cfw_mspi_device_configure_ports *ports)
{
    uint32_t base;
    uint32_t value;
    uint32_t pad_output;
    const open_cfw_mspi_device_mode *mode;

    if (instance->device_configuration >= 26U) return 0U;
    mode = &open_cfw_device_modes[instance->device_configuration];
    base = OPEN_CFW_MSPI0_BASE + instance->module * OPEN_CFW_MSPI_STRIDE;
    value = ports->read_reg(ports->context, base + OPEN_CFW_MSPI_DEV0CFG);
    value = (value & ~0x1FU) | mode->device;
    value = (value & ~(1UL << 25)) | ((uint32_t)mode->separate_io << 25);
    ports->write_reg(ports->context, base + OPEN_CFW_MSPI_DEV0CFG, value);
    value = ports->read_reg(ports->context, base + OPEN_CFW_MSPI_DEV0XIP);
    value = (value & ~(0xFUL << 8)) | ((uint32_t)mode->mixed << 8);
    ports->write_reg(ports->context, base + OPEN_CFW_MSPI_DEV0XIP, value);
    pad_output = mode->pad_output;
    if (instance->clock_on_d4 != 0U && mode->d4_pad_output != 0U)
        pad_output = mode->d4_pad_output;
    ports->write_reg(ports->context, base + OPEN_CFW_MSPI_PADOUTEN, pad_output);
    return 0U;
}
